"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["60301"],{59948(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.recurso_da_etapa.ancora_em_ato_congelante","status":422,"titulo":"O evento que inicia o prazo do recurso da etapa n\xe3o pode ser o ato que congela a configura\xe7\xe3o; escolha outro ato"},"descricao":{"codigo":"uniplus.selecao.recurso_da_etapa.ancora_em_ato_congelante","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["O prazo de recurso de uma etapa \xe9 contado a partir de um tipo de ato que **congela a\\nconfigura\xe7\xe3o** do processo seletivo, como a publica\xe7\xe3o do pr\xf3prio edital.","O ato que congela a configura\xe7\xe3o fixa as regras do certame e n\xe3o \xe9 uma decis\xe3o sobre\\ncandidato. Contar o prazo a partir dele faria a regra de recurso depender de um ato que\\nnunca \xe9 resultado, e a configura\xe7\xe3o de que a regra faz parte deixaria de ser\\nreproduz\xedvel. O recurso cab\xedvel \xe9 contra o **resultado preliminar** da etapa, e \xe9\\nda publica\xe7\xe3o dele que o prazo come\xe7a."],"comoResolver":["A mensagem da recusa nomeia o tipo de ato declarado como in\xedcio do prazo. Aponte a regra\\npara o resultado preliminar que a pr\xf3pria etapa publica.","Se esse resultado ainda n\xe3o est\xe1 entre os produtos da etapa, acrescente-o, com papel\\npreliminar, e conte o prazo a partir dele. Se o prazo na verdade corre da comunica\xe7\xe3o do parecer ao\\ncandidato, declare a ci\xeancia individual como in\xedcio do prazo, em vez de um ato publicado."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);